namespace Retro.App;

internal sealed record NewsText(string Spanish, string English)
{
    public string In(string language) => language == "en" ? English : Spanish;
}

internal enum NewsKind { Feature, Improvement, Fix }
internal sealed record NewsItem(NewsKind Kind, NewsText Title, NewsText Description)
{
    public string KindIn(string language) => Kind switch
    {
        NewsKind.Feature => language == "en" ? "New feature" : "Nueva función",
        NewsKind.Fix => language == "en" ? "Fix" : "Corrección",
        _ => language == "en" ? "Improvement" : "Mejora"
    };
}
internal sealed record ReleaseNote(string Version, IReadOnlyList<NewsItem> Items);

/// <summary>Offline, bilingual history of published versions. Add each release here before shipping it.</summary>
internal static class ReleaseNotes
{
    private static NewsItem N(string es, string en, string detailEs, string detailEn) => new(NewsKind.Feature, new(es, en), new(detailEs, detailEn));
    private static NewsItem I(string es, string en, string detailEs, string detailEn) => new(NewsKind.Improvement, new(es, en), new(detailEs, detailEn));
    private static NewsItem F(string es, string en, string detailEs, string detailEn) => new(NewsKind.Fix, new(es, en), new(detailEs, detailEn));

