    internal static string? ValidVersion(string? value) => value is { Length: <= 32 } && System.Version.TryParse(value, out var version)
        ? new Version(version.Major, version.Minor, Math.Max(0, version.Build)).ToString(3) : null;

    public static IReadOnlyList<ReleaseNote> Since(string? from, string to)
    {
        string? target = ValidVersion(to);
        if (target == null) return [];
        var end = Version.Parse(target);
        var start = ValidVersion(from) is { } prior ? Version.Parse(prior) : null;
        return All.Where(release => Version.Parse(release.Version) <= end
            && (start == null || Version.Parse(release.Version) > start || start >= end && release.Version == target)).ToArray();
    }
}
